#!/usr/bin/env python3
"""Enrichissement ciblé DX2 ; refuse de réécrire un fichier déjà modifié."""
from pathlib import Path
import re,json,gzip,hashlib
from enrichir import para,insert_start
BASE=Path(__file__).resolve().parent
P=BASE.parents[2]/'LOT_018/LOT_018_Phase_B_V0_DX.2.html'

ADDITIONS={
1:para('Classer l’opacité sans confondre ses causes.', 'La classification anatomique précise le siège : noyau, cortex ou région sous-capsulaire postérieure. La classification étiologique distingue vieillissement, traumatisme, maladie oculaire ou générale, exposition médicamenteuse et formes congénitales. Le siège peut orienter la recherche, mais il ne démontre pas à lui seul une cause : une opacité sous-capsulaire postérieure conduit notamment à rechercher diabète et corticothérapie dans le contexte clinique.',10)+para('Distinguer cataracte secondaire et cataracte liée à une autre maladie.', 'Après chirurgie, l’expression « cataracte secondaire » désigne habituellement l’opacification de la capsule postérieure laissée en place pour porter l’implant. Avant chirurgie, une cataracte peut être secondaire à une uvéite ou à un traitement sans désigner cette complication capsulaire. Il faut préciser quel tissu est devenu opaque et si le cristallin naturel est encore présent.',10,36),
2:para('Lire l’histoire naturelle selon le contexte.', 'La cataracte liée à l’âge progresse habituellement lentement, avec un retentissement parfois différent entre les deux yeux. Une cataracte contusive peut apparaître après le choc ou se révéler bien plus tard : l’ancienneté du traumatisme ne suffit pas à l’exclure. Une cataracte chez un sujet jeune fait rechercher une cause traumatique, inflammatoire, métabolique, iatrogène ou congénitale selon l’histoire.',10)+para('Ne pas confondre charge de maladie et décision individuelle.', 'Le nombre d’interventions dépend aussi de l’accès aux soins et des indications opératoires. Il ne mesure pas directement la fréquence des opacités symptomatiques dans la population. Pour un patient, l’enjeu est la perte d’autonomie, l’éblouissement et la limitation des tâches importantes ; une fréquence élevée chez les personnes âgées ne rend pas une baisse soudaine compatible avec une cataracte ordinaire.',10,34),
3:para('Séparer mise au point et transparence.', 'La myopisation nucléaire provient d’une augmentation de l’indice du cristallin. Elle peut améliorer temporairement la lecture sans lunettes chez une personne presbyte, alors que la transparence continue de se dégrader. Un changement de correction peut donc apporter un bénéfice partiel sans arrêter l’évolution. L’éblouissement, les halos et la perte de qualité de l’image résultent de la perturbation du passage de la lumière et ne sont pas toujours résumés par l’acuité centrale.',10,34)+para('Comprendre les complications cristalliniennes.', 'Un cristallin intumescent augmente de volume et peut contribuer à un blocage pupillaire avec fermeture de l’angle : le mécanisme est alors <em>phacomorphique</em>. Des protéines cristalliniennes peuvent aussi obstruer le trabéculum dans le mécanisme <em>phacolytique</em>. Une réaction immunologique aux protéines cristalliniennes peut provoquer une uvéite. Ces mécanismes expliquent pourquoi douleur, rougeur ou hypertonie changent l’urgence au lieu d’être considérées comme une simple aggravation du flou.',10),
4:para('Rechercher une rupture du tableau habituel.', 'Une baisse instantanée, un déficit du champ, des éclairs nouveaux ou une déformation des lignes ne sont pas expliqués par la seule présence d’une opacité cristallinienne. Une cataracte peut coexister avec une occlusion vasculaire, un décollement ou une maculopathie. Le mode d’installation et le signe inexpliqué le plus préoccupant doivent guider l’orientation, même si l’opacité paraît importante.',2,10)+para('Après chirurgie, ne pas attendre une présentation complète.', 'Les Hôpitaux universitaires de Genève demandent un contact rapide devant une baisse de vision, une rougeur ou une douleur inhabituelle sans attendre le rendez-vous prévu. La douleur et l’hypopion soutiennent notamment l’hypothèse d’endophtalmie, mais leur absence ne justifie pas d’ignorer une baisse nouvelle. Une opacification capsulaire ne doit pas devenir l’explication automatique de toute baisse chez le pseudophaque.',10,35,36),
5:para('Documenter le retentissement qui motive la décision.', 'Faire préciser la tâche limitée : lire, reconnaître les visages, se déplacer ou conduire la nuit. Une gêne importante à l’éblouissement peut contraster avec une acuité de cabinet encore assez bonne. Demander si le patient voit plusieurs contours avec un seul œil ou si les couleurs paraissent différentes entre les yeux. Rechercher aussi un changement récent de lunettes pour confronter la plainte au mécanisme cristallinien.',10,34)+para('Préparer une intervention réalisable et sûre.', 'Recueillir les opérations et maladies oculaires antérieures, les traitements complets, les allergies et une infection récente. Les Hôpitaux universitaires de Genève demandent aussi de signaler une claustrophobie et d’organiser l’accompagnement au retour. La capacité à rester installé, à communiquer pendant une anesthésie locale et à suivre les soins doit être discutée avec l’équipe. Ne pas arrêter seul un traitement pour préparer l’intervention.',10,35),
6:para('Comparer la fonction à l’opacité observée.', 'Mesurer chaque œil de loin et de près avec la meilleure correction, puis apprécier la fonction binoculaire. Une amélioration après modification de la correction révèle une composante réfractive ; elle ne fait pas disparaître l’opacité. À la lampe à fente, préciser siège et étendue de la cataracte, puis examiner cornée, chambre antérieure et pupille. Le diagnostic ne se limite pas à constater qu’un cristallin est moins transparent.',10)+para('Rechercher ce qui limitera la récupération.', 'L’examen du fond d’œil recherche notamment une maculopathie, une rétinopathie et une déchirure ; la papille et la pression contribuent à l’évaluation du glaucome. Une fragilité endothéliale cornéenne peut modifier le risque postopératoire. Lorsque la cataracte empêche l’observation, noter cette limite et compléter le bilan : un fond d’œil inaccessible ne doit pas être décrit comme normal.',10),
7:para('Relier les symptômes à une forme plausible.', 'Une baisse de loin avec changement vers une correction plus myopique oriente vers une composante nucléaire. Une gêne de loin et de près avec éblouissement peut accompagner une opacité sous-capsulaire postérieure. Des opacités corticales peuvent produire une autre distribution de la gêne. Ces associations guident l’examen, mais la lampe à fente reste nécessaire pour qualifier le siège réel et rechercher plusieurs formes associées.',10)+para('Reprendre le raisonnement chez le pseudophaque.', 'Une baisse progressive avec éblouissement après une bonne récupération peut être due à la capsule postérieure. Une baisse avec métamorphopsies fait rechercher la macula, notamment un œdème postopératoire. Des éclairs ou un rideau orientent vers la rétine périphérique, tandis qu’une rougeur ou une douleur inhabituelle appelle une évaluation urgente. La présence d’un implant ne localise pas à elle seule le mécanisme du nouveau déficit.',10,35,36),
8:para('Distinguer diagnostic, responsabilité et indication.', 'Voir une opacité établit la présence d’une cataracte. Attribuer la plainte à cette cataracte exige une concordance avec la chronologie, la réfraction et l’examen des autres structures. Décider d’opérer ajoute la question du bénéfice pour le patient, des risques et des autres motifs : permettre l’examen ou le traitement du fond d’œil, ou traiter une complication cristallinienne.',10)+para('Expliquer une incertitude pronostique réelle.', 'La transparence restaurée ne garantit pas une acuité normale si une maladie maculaire, cornéenne ou du nerf optique limite déjà la vision. Si le fond d’œil est peu accessible, les examens complémentaires réduisent certaines incertitudes sans nécessairement établir tout le potentiel visuel. L’information doit distinguer ce que la chirurgie peut corriger de ce qui dépend d’une affection associée.',10),
9:para('Différencier diagnostic clinique et calcul de l’implant.', 'La lampe à fente confirme l’opacité. La biométrie mesure notamment la longueur axiale et s’associe à la kératométrie pour calculer la puissance de l’implant. Le référentiel décrit la biométrie optique non contact et la biométrie ultrasonore en mode A, utile lorsque les milieux empêchent une mesure optique adaptée. L’échographie en mode B répond à une autre question : rechercher une anomalie du segment postérieur caché, par exemple un décollement ou une masse.',10)+para('Interpréter les résultats avant de choisir.', 'Une anomalie maculaire à la tomographie en cohérence optique peut expliquer une part du déficit et modifier le bénéfice attendu. Des mesures biométriques discordantes doivent être vérifiées avant le choix de l’implant. Un implant torique nécessite également l’évaluation de la composante astigmatique et de son orientation. La précision du calcul ne démontre pas, à elle seule, que la rétine fonctionnera normalement après chirurgie.',10)+para('Ne pas appliquer l’échographie sans précaution traumatique.', 'Si une cataracte ou une opacité du fond s’inscrit dans un contexte faisant suspecter un globe ouvert, l’échographie oculaire est contre-indiquée. Ne pas comprimer l’œil pour obtenir l’examen ; l’évaluation ophtalmologique chirurgicale urgente et l’imagerie adaptée au traumatisme priment. Cette exception reste applicable lorsque le fond d’œil est inaccessible.',33),
10:para('Passer de la gêne à une décision partagée.', 'Si la baisse est progressive, mesurer la correction optimale et vérifier que la cataracte explique les limitations. Si une autre lésion participe au déficit, intégrer son traitement et son pronostic à la discussion. Si les activités restent satisfaisantes sans complication ni obstacle au soin du fond d’œil, convenir d’un suivi plutôt que déduire l’urgence de la seule présence de l’opacité.',10)+para('Vérifier chaque condition avant l’intervention et au retour.', 'Si la chirurgie est retenue, confirmer le projet visuel, les mesures de l’implant, l’anesthésie et l’organisation postopératoire. Après l’intervention, une nouvelle baisse de vision, une rougeur ou une douleur inhabituelle déclenche une réévaluation rapide. Une baisse tardive progressivement évocatrice d’opacification capsulaire doit être confirmée avant de proposer un laser.',10,35,36),
11:para('Relier les étapes chirurgicales au résultat.', 'La phacoémulsification fragmente et aspire le contenu du cristallin par une petite incision. La capsule conservée sert habituellement de support à l’implant. Celui-ci remplace la puissance optique retirée ; il ne reproduit pas nécessairement l’accommodation du cristallin jeune. Une fragilité ou une rupture capsulaire peut modifier la technique d’implantation et les risques, ce qui relève de l’information individualisée du chirurgien.',10,34)+para('Choisir l’implant avec ses compromis.', 'Un implant monofocal vise une distance de mise au point choisie ; une correction peut rester nécessaire aux autres distances. Un implant torique ajoute la correction d’un astigmatisme et doit être orienté. Un implant multifocal répartit la lumière entre plusieurs foyers pour diminuer la dépendance aux lunettes, au prix possible de halos et d’une moindre performance visuelle dans certaines situations. Les habitudes, la gêne nocturne et les maladies oculaires associées doivent donc entrer dans le choix.',10)+para('Organiser surveillance et retour sans banaliser une baisse.', 'Le parcours des Hôpitaux universitaires de Genève prévoit une évaluation après l’intervention, des contrôles rapprochés et une correction optique après la récupération initiale. L’équipe vérifie que le patient peut appliquer les soins et dispose d’un accompagnement approprié. La reprise de la conduite est décidée avec l’ophtalmologue. Les collyres prescrits visent notamment inflammation et prévention infectieuse ; aucun schéma posologique non vérifié dans l’information professionnelle suisse n’est proposé ici.',35)+para('Distinguer les complications qui changent la prise en charge.', 'L’endophtalmie peut menacer rapidement la fonction visuelle et nécessite une prise en charge spécialisée urgente. Un œdème maculaire inflammatoire peut expliquer une récupération insuffisante ou une baisse secondaire avec déformation des lignes. Une opacification capsulaire ultérieure relève parfois d’une capsulotomie laser, après confirmation de son rôle. Une complication rétinienne reste possible et ne doit pas être confondue avec la capsule simplement parce que l’œil a déjà été opéré.',10,35,36),
12:para('Agir sur les causes évitables sans promettre une prévention universelle.', 'La protection oculaire vise les traumatismes ; la révision des traitements identifie notamment une exposition aux corticoïdes sans imposer leur arrêt lorsqu’ils sont nécessaires. Le contrôle d’une maladie associée et l’examen des symptômes favorisent une prise en charge adaptée. Aucun collyre n’est établi dans les sources lues pour prévenir ou faire disparaître la cataracte liée à l’âge.',10)+para('Prévenir le retard et les complications du parcours.', 'Après l’opération, les consignes des Hôpitaux universitaires de Genève insistent sur l’hygiène des mains, l’absence de frottement de l’œil et l’application des traitements prescrits. Le patient doit savoir contacter l’équipe devant une baisse, une rougeur ou une douleur inhabituelle. Chez l’enfant, l’enjeu de dépistage est différent : une opacité peut priver le système visuel d’une image nette pendant son développement et favoriser l’amblyopie.',10,35),
13:para('Raisonner au-delà de l’opacité.', 'La plainte doit correspondre au cristallin, à son évolution et à sa conséquence sur les activités. La réfraction montre ce que les lunettes peuvent encore améliorer ; l’examen de la cornée, de la macula et du nerf estime les limites du bénéfice. La biométrie prépare l’implant, sans remplacer le diagnostic clinique. Après chirurgie, tout changement inattendu doit être réévalué avant de conclure à une simple capsule opaque.',10,35,36)+para('Garder les urgences visibles.', 'Une cataracte ordinaire ne suffit pas à expliquer une perte instantanée ou un œil rouge douloureux. Une cataracte compliquée peut provoquer inflammation ou hypertonie ; une autre maladie peut coexister. Chez l’enfant, le calendrier spécialisé protège aussi le développement visuel. La décision et le suivi doivent donc répondre au mécanisme et au risque du patient, et non seulement au nom de cataracte.',1,2,10),
14:para('Défendre une décision, pas seulement un diagnostic.', 'Pour répondre, préciser ce qui permet d’attribuer la gêne au cristallin, l’examen qui recherche une autre cause et la conséquence thérapeutique. Les confusions les plus utiles à prévenir sont celles entre réfraction et transparence, diagnostic et calcul d’implant, capsule et cristallin, récupération anatomique et fonction réelle. Une alerte postopératoire doit conduire à une action explicite.',10,35,36)
}

REPONSES=[
'La chirurgie restaure un milieu optique ; une lésion de la macula ou du nerf peut limiter le bénéfice même si l’implant est bien placé.',
'L’augmentation de l’indice cristallinien peut améliorer provisoirement la vision de près sans signifier une guérison. La réfraction et la lampe à fente doivent être confrontées.',
'Interroger les activités en lumière vive et la conduite nocturne permet d’apprécier un retentissement mal résumé par l’échelle d’acuité.',
'Une cataracte intumescente ou une complication inflammatoire peut modifier le tableau. Douleur, rougeur et hypertonie imposent une évaluation adaptée.',
'Elle permet de préciser siège et étendue ; la responsabilité fonctionnelle reste à confronter à la réfraction et aux autres structures.',
'La présence d’une cataracte ne démontre pas que toute la baisse vient du cristallin. L’examen et l’imagerie maculaire adaptée servent aussi à informer sur le potentiel visuel.',
'Un obstacle à l’examen ou au traitement du fond d’œil et une complication cristallinienne constituent aussi des motifs de discussion chirurgicale.',
'La longueur axiale et la kératométrie servent au calcul. Le mode B échographique explore le segment postérieur caché et répond à une question différente.',
'Le projet doit préciser la distance visée. Les options multifocales et toriques apportent des fonctions différentes avec leurs propres compromis.',
'Les cellules résiduelles opacifient la capsule qui porte l’implant. Une capsulotomie se discute après confirmation, sans attribuer automatiquement tout nouveau flou à cette cause.',
'Une baisse nouvelle, une rougeur ou une douleur inhabituelle justifient le contact urgent demandé par l’équipe ; il ne faut pas attendre que tous les signes soient réunis.',
'Le risque concerne la maturation visuelle. La prise en charge pédiatrique et le traitement de l’amblyopie éventuelle ne sont pas équivalents au parcours habituel d’une cataracte liée à l’âge.',
'Si un globe ouvert est suspecté après traumatisme, l’échographie est contre-indiquée et il ne faut pas comprimer l’œil. L’évaluation spécialisée urgente choisit l’alternative adaptée.',
'Les traitements postopératoires préviennent ou traitent certaines complications ; ils ne dissolvent pas le cristallin opaque et ne remplacent pas son extraction lorsqu’elle est indiquée.'
]

SOURCES={
33:'Société française d’ophtalmologie. Rapport 2018, Urgences en ophtalmologie, examen aux urgences et traumatismes. <a href="https://www.em-consulte.com/em/SFO/2018/HTML/B9782294753954500138.html">Source</a>. Extrait sur la contre-indication de l’échographie si globe ouvert suspecté relu le 01.11.2026 ; portée de sécurité ciblée.',
34:'Hôpitaux universitaires de Genève. <a href="https://www.hug.ch/ophtalmologie/cataracte">Cataracte</a> et <a href="https://www.hug.ch/ophtalmologie/operation-cataracte">L’opération de la cataracte</a>. Pages d’information consultées le 01.11.2026 : définition, symptômes, principes opératoires.',
35:'Hôpitaux universitaires de Genève. Opération de la cataracte : <a href="https://www.hug.ch/ophtalmologie/operation-cataracte-avant-lintervention">avant l’intervention</a>, <a href="https://www.hug.ch/ophtalmologie/operation-cataracte-pendant-lintervention">pendant</a>, <a href="https://www.hug.ch/ophtalmologie/operation-cataracte-apres-intervention">après</a>. Consultées le 01.11.2026 : organisation locale, surveillance et urgences ; pas de transposition d’un protocole médicamenteux.',
36:'Hôpitaux universitaires de Genève. Cataracte secondaire : <a href="https://www.hug.ch/ophtalmologie/traitement-cataracte-secondaire">définition</a>, <a href="https://www.hug.ch/ophtalmologie/diagnostic-facteurs-risque-cataracte-secondaire">diagnostic</a>, <a href="https://www.hug.ch/ophtalmologie/traitement-cataracte-secondaire-0">traitement</a>. Consultées le 01.11.2026 : capsule, capsulotomie et signes de complication. Les pourcentages variables entre pages ne sont pas repris.'
}

if __name__=='__main__':
    original=gzip.decompress((BASE/(P.name+'.avant.gz')).read_bytes()).decode();assert P.read_text()==original,'Modification existante : arrêt'
    text=original
    new='<div id="dx2-detail13" popover class="fenetre"><div class="barre"><span>Points clés et raisonnement clinique</span><button type="button" popovertarget="dx2-detail13" popovertargetaction="hide" aria-label="Fermer">✕</button></div><div class="corps"></div></div>\n'
    text=text.replace('<div id="dx2-quiz"',new+'<div id="dx2-quiz"',1)
    old='Une cataracte visible doit expliquer la gêne';newbutton='<button type="button" class="terme" popovertarget="dx2-detail13">'+old+'</button>';text=text.replace(old,newbutton,1)
    for point,addition in ADDITIONS.items():text=insert_start(text,'dx2-detail'+str(point) if point<14 else 'dx2-quiz',addition)
    qs=list(re.finditer(r'<details class="quiz">.*?</details>',text,re.S));assert len(qs)==14
    for i,m in reversed(list(enumerate(qs))):
        refs=[10] if i not in [9,10,12] else {9:[36],10:[35],12:[33]}[i]
        chunk=m.group().replace('</details>',para('Raisonnement.',REPONSES[i],*refs)+'</details>');text=text[:m.start()]+chunk+text[m.end():]
    at=text.index('<h2>Sources</h2>');pos=text.index('</ol>',at);newsrc=''.join(f'<li id="s{i}" value="{i}">{v}</li>\n' for i,v in SOURCES.items());text=text[:pos]+newsrc+text[pos:]
    P.write_text(text)
    info=dict(fichier=P.name,sha256_avant=hashlib.sha256(original.encode()).hexdigest(),sha256_apres_insertion=hashlib.sha256(text.encode()).hexdigest(),octets_avant=len(original.encode()),octets_apres=len(text.encode()),complements={('dx2-detail'+str(i) if i<14 else 'dx2-quiz'):x for i,x in ADDITIONS.items()},reponses_ajoutees=REPONSES,sources_ajoutees=SOURCES)
    (BASE/'DX2_ENRICHISSEMENTS_EXACTS.json').write_text(json.dumps(info,ensure_ascii=False,indent=2)+'\n')
    print(P.name,len(original.encode()),'->',len(text.encode()))
